def build_payload():
    arts = []
    for a in ARTICLES:
        arts.append({
            "title": a["title"], "slug": a["slug"], "body": a["body"],
            "excerpt": a["excerpt"], "category": a["category"], "type": a["type"],
            "image_url": None, "image_base64": b64(a["img"]),
            "sources": a["sources"], "source_type": a["source_type"],
        })
    return {"articles": arts}

def post(payload):
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(ENDPOINT, data=data, method="POST")
    req.add_header("Content-Type", "application/json")
    req.add_header("x-agent-secret", SECRET)
    with urllib.request.urlopen(req, timeout=120) as r:
        return r.status, json.loads(r.read().decode("utf-8"))

if __name__ == "__main__":
    if not SECRET:
        print("ERROR: AGENT_PUBLISH_SECRET missing"); sys.exit(2)
    # validation
    assert len(ARTICLES) == 8, "must be 8 articles"
    assert sum(1 for a in ARTICLES if a["source_type"] == "news") == 5
    assert sum(1 for a in ARTICLES if a["source_type"] == "trend") == 3
    for a in ARTICLES:
        assert "—" not in a["title"] + a["excerpt"] + a["body"], f"em-dash in {a['slug']}"
        assert a["sources"], f"empty sources {a['slug']}"
    payload = build_payload()
    if "--dry" in sys.argv:
        for a in payload["articles"]:
            wc = len(a["body"].split())
            print(f"{a['slug']:48} type={a['type']:12} words={wc:4} img_b64={len(a['image_base64'])}")
        print("DRY OK")
        sys.exit(0)
    status, body = post(payload)
    print("HTTP", status)
    print(json.dumps(body, ensure_ascii=False, indent=2))
    with open("/tmp/publish_result.json", "w", encoding="utf-8") as f:
        json.dump({"run_id": RUN_ID, "generated_at": NOW, "results": body}, f, ensure_ascii=False)
